#include <stdio.h>

static const char *describe(int code) {
  const char *Err;
  if (code == 0) {
    Err = "ok";
  } else {
    Err = "bad";
  }
  return Err;
}

int main(void) {
  printf("%s\n", describe(0));
  printf("%s\n", describe(1));
  return 0;
}



